// === Tab: mySketch ===
let numStars = 2000;
let stars = [];

function setup() {
  createCanvas(windowWidth, windowHeight, P2D);
  colorMode(HSB, 360, 100, 100);
  noStroke();
  // Precompute star positions in a spiral
  for (let i = 0; i < numStars; i++) {
    let angle = random(TWO_PI) + i * 0.17;
    let radius = pow(random(1), 1.7) * max(width, height) * 0.4;
    let spiralness = 0.7;
    let a = angle + spiralness * log(radius + 1); // spiral arms
    let x = width / 2 + cos(a) * radius;
    let y = height / 2 + sin(a) * radius;

    let hue = 210 + random(-30, 30); // blueish
    let bright = random(80, 100);

    stars.push({x, y, hue, bright, size: random(0.5, 2)});
  }
  background(0);
}

function draw() {
  // Animates the galaxy rotation
  background(0, 0.1); // keep old stars for a dreamy trail effect
  translate(width / 2, height / 2);
  rotate(frameCount * 0.0008);

  for (let s of stars) {
    fill(s.hue, 40, s.bright);
    ellipse(s.x - width/2, s.y - height/2, s.size, s.size);
  }
}

